<?php
require __DIR__.'/app/bootstrap.php';$u=require_user(false);$title=t('Account settings');$err=[];$action='';
if(post()){
 $action=val('action');
 if($action==='profile'){
  $name=val('full_name');$phone=val('phone');$dob=val('dob');$address=val('delivery_address');$tz=new DateTimeZone(cfg('timezone'));$d=DateTimeImmutable::createFromFormat('!Y-m-d',$dob,$tz);$today=new DateTimeImmutable('today',$tz);
  if(!text_valid($name,2,120))$err[]=t('Enter your full name (2–120 characters).');
  if(!preg_match('/^\+?[0-9 ()-]{8,25}$/',$phone)||strlen(preg_replace('/\D/','',$phone))<8)$err[]=t('Enter a valid phone number with country code.');
  if(!$d||$d->format('Y-m-d')!==$dob||$d>$today||$d<$today->modify('-120 years'))$err[]=t('Enter a valid date of birth.');
  $point=coordinates(val('latitude'),val('longitude'));if(experience_ready())location_required_error($err,$address,$point);elseif(!text_valid($address,0,1000))$err[]=t('Delivery address must be under 1000 characters.');
  if(!$err){db()->beginTransaction();q('UPDATE users SET full_name=?,phone=?,dob=?,delivery_address=? WHERE id=?',[$name,$phone,$dob,$address,$u['id']]);if(experience_ready())save_location((int)$u['id'],$point);db()->commit();flash(t('Your profile has been updated.'));go('settings.php');}
 }elseif($action==='email'){
  if(!update02_ready())$err[]='The account update is not installed yet. Please ask the administrator to complete the update.';
  elseif(!limit('change-email',5,3600))$err[]=t('Too many email change requests. Please try again in an hour.');
  $email=strtolower(val('new_email'));
  if(!email_valid($email))$err[]=t('Enter a valid new email address.');
  if($email===$u['email'])$err[]=t('Enter a different email address.');
  if(!password_verify(raw('email_password'),$u['password_hash']))$err[]=t('Your current password is incorrect.');
  if(!$err){try{db()->beginTransaction();
   if(one('SELECT id FROM users WHERE email=?',[$email])){$err[]=t('This email address is already registered.');db()->rollBack();}
   else{q('DELETE FROM email_changes WHERE expires_at<=?',[now()]);q('DELETE FROM email_changes WHERE user_id=?',[$u['id']]);$token=bin2hex(random_bytes(32));
    q('INSERT INTO email_changes (user_id,new_email,old_email,session_version,token_hash,expires_at,created_at) VALUES (?,?,?,?,?,?,?)',[$u['id'],$email,$u['email'],$u['session_version'],hash('sha256',$token),gmdate('Y-m-d H:i:s',time()+3600),now()]);
    queue_mail($email,t('Confirm your new Zayqah email'),"Hello {$u['full_name']},\nConfirm your new email address within one hour:\n".url('confirm-email.php?token='.$token)."\nYour current email will remain active until you confirm this change.");db()->commit();mail_after_commit();flash(t('Verification queued for your new email. Your current email stays active until you confirm it.'));go('settings.php#email');}
  }catch(PDOException $ex){if(db()->inTransaction())db()->rollBack();if(in_array((string)$ex->getCode(),['23000','23505']))$err[]=t('This email address is already registered or awaiting confirmation.');else throw $ex;}}
 }elseif($action==='cancel-email'){
  if(update02_ready())q('DELETE FROM email_changes WHERE user_id=?',[$u['id']]);flash(t('Pending email change cancelled.'));go('settings.php#email');
 }elseif($action==='password'){
  if(!limit('change-password',5,3600))$err[]=t('Too many password change attempts. Please try again in an hour.');
  if(!password_verify(raw('current_password'),$u['password_hash']))$err[]=t('Your current password is incorrect.');
  $err=array_merge($err,password_errors(raw('password'),raw('password_confirm')));
  if(!$err){db()->beginTransaction();$changed=q('UPDATE users SET password_hash=?,session_version=session_version+1 WHERE id=? AND session_version=?',[password_hash(raw('password'),PASSWORD_DEFAULT),$u['id'],$u['session_version']])->rowCount();
   if($changed!==1){db()->rollBack();$err[]=t('Your account changed in another session. Sign in again before changing your password.');}
   else{q('DELETE FROM tokens WHERE user_id=? AND purpose=?',[$u['id'],'reset']);if(update02_ready())q('DELETE FROM email_changes WHERE user_id=?',[$u['id']]);db()->commit();session_regenerate_id(true);$_SESSION['version']=(int)$u['session_version']+1;flash(t('Password updated. Other sessions have been signed out and pending email changes cancelled.'));go('settings.php#password');}
  }
 }else $err[]=t('Unknown settings action.');
}
$pending=update02_ready()?one('SELECT new_email,expires_at FROM email_changes WHERE user_id=? AND session_version=? AND expires_at>?',[$u['id'],$u['session_version'],now()]):null;
function profile_value(string $key): string {global $u,$action;return $_SERVER['REQUEST_METHOD']==='POST' && $action==='profile'?val($key):(string)($u[$key]??'');}
require ROOT.'/app/header.php'; ?>
<main class="page shell" id="main"><div class="dash-header"><div><span class="heading-kicker"><?=e(t('MAKE YOURSELF AT HOME'))?></span><h1><?=e(t('Account settings'))?></h1><p><?=e(t('Keep your details up to date and your account secure.'))?></p></div><a class="pill" href="<?=e(url('accounts.php'))?>"><?=e(t('← My Account'))?></a></div><?php errors($err); ?><div class="settings-layout"><nav class="settings-nav" aria-label="<?=e(t('Account settings'))?>"><a href="#profile"><?=e(t('Personal details'))?></a><a href="#email"><?=e(t('Email address'))?></a><a href="#password"><?=e(t('Password & security'))?></a><a href="<?=e(url('index.php'))?>"><?=e(t('Explore Food →'))?></a></nav><div class="settings-sections">
<section class="panel padded" id="profile"><h2><?=e(t('Personal details'))?></h2><p class="hint"><?=e(t('Update your name, phone number and delivery address.'))?></p><form method="post"><?=csrf()?><input type="hidden" name="action" value="profile"><div class="form-grid"><?php field('full_name',t('Full name'),'text','required minlength="2" maxlength="120" autocomplete="name"',profile_value('full_name'));field('dob',t('Date of birth'),'date','required max="'.e((new DateTimeImmutable('today',new DateTimeZone(cfg('timezone'))))->format('Y-m-d')).'"',profile_value('dob'));field('phone',t('Phone number'),'tel','required maxlength="25" autocomplete="tel"',profile_value('phone')); ?></div><?php area('delivery_address',t('Your address'),profile_value('delivery_address'),'required minlength="10" maxlength="1000" autocomplete="street-address"');if(experience_ready()){$pin=saved_location((int)$u['id']);location_picker($_SERVER['REQUEST_METHOD']==='POST'&&$action==='profile'?val('latitude'):(string)($pin['latitude']??''),$_SERVER['REQUEST_METHOD']==='POST'&&$action==='profile'?val('longitude'):(string)($pin['longitude']??''));} ?><button class="pill primary space-top"><?=e(t('Save personal details'))?></button></form></section>
<section class="panel padded" id="email"><h2><?=e(t('Email address'))?></h2><p><?=e(t('Current email:'))?> <strong><?=e($u['email'])?></strong></p><p class="hint"><?=e(t('Confirm with your current password. We’ll verify the new address before changing your login email.'))?></p><?php if($pending): ?><div class="alert"><?=e(t('Waiting for confirmation:'))?> <strong><?=e($pending['new_email'])?></strong><br><?=e(t('Link expires'))?> <?=e(local_time($pending['expires_at']))?>.</div><form method="post"><?=csrf()?><input type="hidden" name="action" value="cancel-email"><button class="pill"><?=e(t('Cancel pending change'))?></button></form><?php endif ?><form method="post"><?=csrf()?><input type="hidden" name="action" value="email"><div class="form-grid"><?php field('new_email',t('New email address'),'email','required maxlength="254" autocomplete="email"');field('email_password',t('Current password'),'password','required autocomplete="current-password" maxlength="72"'); ?></div><button class="pill primary space-top"><?=e(t('Verify new email →'))?></button></form></section>
<section class="panel padded" id="password"><h2><?=e(t('Password & security'))?></h2><p class="hint"><?=e(t('Use a unique password with 8–72 characters. Your other sessions will be signed out.'))?></p><form method="post"><?=csrf()?><input type="hidden" name="action" value="password"><?php field('current_password',t('Current password'),'password','required autocomplete="current-password" maxlength="72"'); ?><div class="form-grid"><?php field('password',t('New password'),'password','required minlength="8" maxlength="72" autocomplete="new-password"');field('password_confirm',t('Confirm new password'),'password','required minlength="8" maxlength="72" autocomplete="new-password"'); ?></div><button class="pill primary space-top"><?=e(t('Update password'))?></button></form></section></div></div></main><?php require ROOT.'/app/footer.php'; ?>
